#include <iostream>

int main() {
    int num1 = 0;
    int num2 = 0;

    if (std::cin >> num1 >> num2) {
        if (num1 == num2) {
            std::cout << num1 << " is equal to " << num2 << "\n";
        }
        if (num1 != num2) {
            std::cout << num1 << " is not equal to " << num2 << "\n";
        }
        if (num1 < num2) {
            std::cout << num1 << " is less than " << num2 << "\n";
        }
        if (num1 > num2) {
            std::cout << num1 << " is greater than " << num2 << "\n";
        }
        if (num1 <= num2) {
            std::cout << num1 << " is less than or equal to " << num2 << "\n";
        }
        if (num1 >= num2) {
            std::cout << num1 << " is greater than or equal to " << num2 << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <string>
#include <string_view>

void demonstrate_secure_output(std::string_view greeting, std::string_view name) {
    // Equivalent to secure puts() pattern: outputs string with trailing newline
    std::cout << greeting << "\n";

    // Equivalent to secure printf("%s", ...): no format injection possible
    std::cout << "User: " << name << "\n";
}

int main() {
    std::string user_name;
    if (std::cin >> user_name) {
        demonstrate_secure_output("Welcome to C++!", user_name);
    }
    return 0;
}
